class TestStaticAnalysis:
    def test_perform_static_analysis_python(self, generator):
        code = "import os\ndef test_func(a, b):\n    if a > b: return True\n    return False"
        result = generator._perform_static_analysis(code, Language.PYTHON)
        
        assert isinstance(result, AnalysisResult)
        assert len(result.functions) == 1
        assert result.functions[0]['name'] == 'test_func'
        assert result.functions[0]['args'] == ['a', 'b']
        assert len(result.critical_points) == 1
        assert 'os' in result.dependencies

    def test_perform_static_analysis_non_python(self, generator):
        code = "fn main() { println!(\"Hello\"); }"
        result = generator._perform_static_analysis(code, Language.RUST)
        
        assert result.functions == []
        assert result.dependencies == set()
        assert result.complexity_score == 0

