class TestSynthesisLogic:
    def test_extract_control_flow(self, generator):
        analysis = AnalysisResult(
            functions=[{"name": "func1", "args": [], "line": 1, "body_len": 5}],
            critical_points=[{"func": "func1", "line": 2, "type": "branch"}],
            dependencies=set(),
            complexity_score=1
        )
        cfg = generator._extract_control_flow(analysis, "")
        assert "func1" in cfg
        assert len(cfg["func1"]) == 1

    def test_synthesize_test_cases(self, generator):
        analysis = AnalysisResult(
            functions=[{"name": "add", "args": ["x", "y"], "line": 1, "body_len": 2}],
            critical_points=[{"func": "add", "line": 2, "type": "branch"}],
            dependencies=set(),
            complexity_score=1
        )
        cfg = {"add": analysis.critical_points}
        
        tests = generator._synthesize_test_cases(
            analysis, cfg, Framework.PYTEST, TestDepth.UNIT, MockStrategy.AUTO
        )
        
        # Should have 1 happy path + 1 boundary case
        assert len(tests) == 2
        assert any(t['scenario'] == "Happy Path" for t in tests)
        assert any("Boundary Condition" in t['scenario'] for t in tests)
        assert "arg_x, arg_y" in tests[0]['logic']

    def test_generate_mocks(self, generator):
        deps = {"requests", "pandas"}
        mocks = generator._generate_mocks(deps, MockStrategy.AUTO)
        
        assert "requests_mock = MagicMock()" in mocks
        assert "pandas_mock = MagicMock()" in mocks
        assert "# Auto-generated Mocks" in mocks

    def test_generate_mocks_empty(self, generator):
        assert generator._generate_mocks(set(), MockStrategy.AUTO) == ""

