class TestSandboxExecution:
    def test_refine_in_sandbox_success(self, generator):
        test_cases = [{"target": "my_func", "scenario": "Happy Path", "logic": "assert True"}]
        mocks = "mock_val = 1"
        
        # Mock subprocess.run to avoid actually calling pytest in the test environment
        with patch("subprocess.run") as mock_run:
            mock_run.return_value = MagicMock(returncode=0, stdout="passed", stderr="")
            
            artifacts = generator._refine_in_sandbox(
                test_cases, mocks, "source.py", Framework.PYTEST
            )
            
            assert len(artifacts) == 1
            assert isinstance(artifacts[0], TestArtifact)
            assert "def test_my_func_happy_path" in artifacts[0].content
            assert artifacts[0].file_path.name == "test_source.py"

    def test_calculate_predicted_coverage(self, generator):
        analysis = AnalysisResult([], [{"func": "f1", "line": 1}], set(), 1)
        # 1 critical point, 2 tests generated
        artifacts = [TestArtifact(Path("p"), "c", 0.9, ["case1", "case2"])]
        
        report = generator._calculate_predicted_coverage(analysis, artifacts)
        # coverage = min(1.0, 2 / (1 + 1)) = 1.0
        assert report["predicted_branch_coverage"] == 1.0
        assert report["tests_generated"] == 2

