class TestFullPipeline:
    def test_execute_full_flow(self, generator, python_source_file):
        # Mock subprocess to prevent actual pytest execution during E2E test
        with patch("subprocess.run") as mock_run:
            mock_run.return_value = MagicMock(returncode=0, stdout="OK", stderr="")
            
            result = generator.execute(
                source_path=python_source_file,
                language=Language.PYTHON,
                framework=Framework.PYTEST,
                test_depth=TestDepth.UNIT
            )
            
            assert "artifacts" in result
            assert "coverage_report" in result
            assert len(result["artifacts"]) > 0
            assert result["coverage_report"]["total_critical_points"] > 0
            assert "Synthesis completed successfully" in result["execution_log"]

    def test_execute_file_not_found(self, generator):
        with pytest.raises(RuntimeError) as excinfo:
            generator.execute(
                source_path="non_existent_file.py",
                language=Language.PYTHON,
                framework=Framework.PYTEST
            )
        assert "TestGeneratorSkill Error" in str(excinfo.value)

    def test_execute_invalid_python_syntax(self, generator, tmp_path):
        bad_file = tmp_path / "bad.py"
        bad_file.write_text("def broken_syntax(:") # SyntaxError
        
        with pytest.raises(RuntimeError):
            generator.execute(
                source_path=str(bad_file),
                language=Language.PYTHON,
                framework=Framework.PYTEST
            )